#!/usr/bin/env python3
"""One-shot CI reconciliation for the oversized v0.41.62 ledger."""

import base64
import hashlib
from pathlib import Path
import subprocess


ROOT = Path(__file__).resolve().parents[2]
LEDGER = ROOT / "AI_Companion_当前总账.md"
OLD_GIT_BLOB = "2ea38a685c5c1f6cc5cbb86c8e4d6ced58661838"
NEW_GIT_BLOB = "75ef5acdec2ba9bc3921bd12d97b4e2246036d2a"
PATCH_B64 = ""


def git_blob_sha(path: Path) -> str:
    payload = path.read_bytes()
    framed = f"blob {len(payload)}".encode() + b'\0' + payload
    return hashlib.sha1(framed).hexdigest()


def main() -> None:
    actual = git_blob_sha(LEDGER)
    if actual != OLD_GIT_BLOB:
        raise SystemExit(f"unexpected ledger base: {actual}")
    subprocess.run(
        ["git", "apply", "--whitespace=nowarn", "-"],
        cwd=ROOT,
        input=base64.b64decode(PATCH_B64),
        check=True,
    )
    actual = git_blob_sha(LEDGER)
    if actual != NEW_GIT_BLOB:
        raise SystemExit(f"unexpected reconciled ledger: {actual}")
    print(f"v0.41.62 successful-build ledger reconciled: {actual}")


if __name__ == "__main__":
    main()
